form='''<div class="bank"><h1>Banco de ideias.</h1><p class="notice">As alterações ficam salvas neste navegador. Exporte o JSON para guardar uma cópia ou levar a outro computador. Este arquivo não agenda nem publica posts.</p><div id="idea-list"></div><h2 id="form-title">Guardar uma nova ideia</h2><form id="idea-form"><div class="form-grid"><label>Título<input name="title" required></label><label>Mês de interesse<input name="month" type="month" required value="2026-12"></label><label>Formato<input name="format" placeholder="Reel, carrossel, estático..."></label><label>Estado<input name="status" value="Ideia guardada"></label><label>Origem<input name="origin" placeholder="Bruna, histórico, nova sugestão..."></label><label>Data sugerida (opcional)<input name="date" type="date"></label><label class="wide">Ideia / abordagem<textarea name="angle" rows="2"></textarea></label><label class="wide">O que captar<textarea name="capture" rows="2"></textarea></label><label class="wide">O que falta confirmar<textarea name="pending" rows="2"></textarea></label></div><button>Salvar ideia</button><button type="button" onclick="cancelEdit()">Limpar formulário</button><p id="save-message" role="status"></p></form></div>'''
app=head+'<body>'+css+nav+'<div id="diagnostico" class="view">'+diag+'</div><div id="calendario" class="view active"><div id="month-live">'+monthslide(2026,11)+'</div><div class="print-only">'+monthslide(2026,12)+monthslide(2027,1)+'</div></div><div id="ideias" class="view">'+form+'</div><script id="initial-data" type="application/json">'+json.dumps(data,ensure_ascii=False).replace('<','\\u003c')+'</script><script>'+script.read_text()+'</script></body></html>'
